package com.bank.secureupload;

import java.time.Instant;
import java.util.*;
import java.util.logging.*;

public class SecureUploadDemo {
    private static final Logger log = Logger.getLogger(SecureUploadDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        long maxSingle = 100L * 1024 * 1024;    // 100 MB
        long maxTotal = 5L * 1024 * 1024 * 1024; // 5 GB
        long partSize = 16L * 1024 * 1024;       // 16 MB

        PresignService presign = new PresignService("nbi-uploads-raw", 300);
        SizeGuard sizeGuard = new SizeGuard(maxSingle, maxTotal);
        MagicByteValidator validator = new MagicByteValidator(
                Set.of("application/pdf", "image/png", "image/jpeg", "video/mp4"));
        MultipartCoordinator coordinator = new MultipartCoordinator(presign, partSize);
        QuarantineScanner scanner = new QuarantineScanner();

        // Scenario 1: Rajesh uploads a 20 MB PDF — single presigned PUT
        long rajeshSize = 20L * 1024 * 1024;
        sizeGuard.checkSingle(rajeshSize);
        String url = presign.presignPut("SAV2001", "loan_form.pdf").url;
        log.info(() -> "Rajesh single-PUT presigned URL: " + url);

        // Scenario 2: Priya uploads a 3 GB KYC video — multipart upload
        long priyaSize = 3L * 1024 * 1024 * 1024;
        sizeGuard.checkTotal(priyaSize);
        String uploadId = coordinator.initiate("CUR3001", "kyc_video.mp4");
        int parts = coordinator.planParts(priyaSize);
        log.info("Priya multipart initiated id=" + uploadId + " parts=" + parts);
        coordinator.simulateUploadParts("CUR3001", "kyc_video.mp4", uploadId, parts);
        coordinator.complete(uploadId);

        // Scenario 3: spoofed file — .pdf extension but real bytes are an EXE
        byte[] spoofed = new byte[] { 'M', 'Z', 0x90, 0x00 };        // DOS/PE header = executable
        try {
            validator.validate("statement.pdf", "application/pdf", spoofed);
        } catch (UnsupportedFileTypeException e) {
            log.severe("SPOOF REJECTED: " + e.getMessage());
        }

        // Scenario 4: a genuine PDF passes magic-byte check, then quarantine scan
        byte[] realPdf = new byte[] { '%', 'P', 'D', 'F', '-', '1', '.', '7' };
        validator.validate("loan_form.pdf", "application/pdf", realPdf);
        String status = scanner.scan("SAV2001/loan_form.pdf");
        log.info("Rajesh file scan result: " + status);
    }
}

// ─── presign/PresignService.java ───
// Mints short-lived, scoped presigned URLs. Real impl uses software.amazon.awssdk S3Presigner.
class PresignService {
    final String bucket; final long ttl;
        PresignService(String bucket, long ttlSeconds) { this.bucket = bucket;
        this.ttl = ttlSeconds; }
    Presigned presignPut(String userId, String filename) {
        String key = userId + "/" + filename;
        String url = "https://" + bucket + ".s3.amazonaws.com/" + key
                + "?X-Amz-Expires=" + ttl + "&X-Amz-Signature=SIM";
        return new Presigned(key, url, Instant.now().plusSeconds(ttl));
    }
    Presigned presignPart(String key, String uploadId, int partNumber) {
        String url = "https://" + bucket + ".s3.amazonaws.com/" + key
                + "?partNumber=" + partNumber + "&uploadId=" + uploadId + "&X-Amz-Signature=SIM";
        return new Presigned(key, url, Instant.now().plusSeconds(ttl));
    }
}
class Presigned { final String key, url; final Instant expiresAt;
        Presigned(String key, String url, Instant exp) { this.key = key;
        this.url = url
        this.expiresAt = exp; } }

