// ─── multipart/MultipartCoordinator.java ───
// Initiates, tracks parts, and completes an S3 multipart upload.
class MultipartCoordinator {
    private static final Logger log = Logger.getLogger(MultipartCoordinator.class.getName());
    private final PresignService presign; private final long partSize;
    private final Map<String, List<PartInfo>> uploads = new HashMap<>();
        MultipartCoordinator(PresignService presign, long partSize) { this.presign = presign;
        this.partSize = partSize; }

    String initiate(String userId, String filename) {
        String uploadId = "UP-" + UUID.randomUUID();
        uploads.put(uploadId, new ArrayList<>());
        return uploadId;
    }
    int planParts(long totalBytes) { return (int) Math.ceil((double) totalBytes / partSize); }

    void simulateUploadParts(String userId, String filename, String uploadId, int parts) {
        String key = userId + "/" + filename;
        for (int p = 1; p <= parts; p++) {
            Presigned partUrl = presign.presignPart(key, uploadId, p);     // one URL per part
            // client uploads this part directly to S3, receives an ETag
            String etag = "etag-" + p;
            uploads.get(uploadId).add(new PartInfo(p, etag));
            if (p == 1 || p == parts) log.fine("uploaded part " + p + "/" + parts + " via " + partUrl.url);
        }
    }
    void complete(String uploadId) {
        List<PartInfo> parts = uploads.get(uploadId);
        log.info("COMPLETE multipart " + uploadId + " with " + parts.size() + " parts → S3 assembles object");
    }
}

// ─── validate/SizeGuard.java ───
class SizeGuard {
    private final long maxSingle, maxTotal;
        SizeGuard(long maxSingle, long maxTotal) { this.maxSingle = maxSingle;
        this.maxTotal = maxTotal; }
    void checkSingle(long bytes) {
        if (bytes > maxSingle) throw new FileTooLargeException("use multipart above " + maxSingle + " bytes");
    }
    void checkTotal(long bytes) {
        if (bytes > maxTotal) throw new FileTooLargeException("exceeds absolute cap " + maxTotal + " bytes");
    }
}

