// Verifies the REAL file type from leading bytes, ignoring extension and declared type.
class MagicByteValidator {
    private final Set<String> allowed;
    MagicByteValidator(Set<String> allowed) { this.allowed = allowed; }
    void validate(String filename, String declaredType, byte[] head) {
        String actual = detect(head);
        if (actual == null || !allowed.contains(actual))
            throw new UnsupportedFileTypeException(
                    "declared=" + declaredType + " but magic bytes say=" + actual + " for " + filename);
    }
    private String detect(byte[] b) {
        if (startsWith(b, '%', 'P', 'D', 'F')) return "application/pdf";
        if (b.length >= 3 && (b[0] & 0xFF) == 0xFF && (b[1] & 0xFF) == 0xD8) return "image/jpeg";
        if (b.length >= 8 && (b[0] & 0xFF) == 0x89 && b[1] == 'P' && b[2] == 'N' && b[3] == 'G') return "image/png";
        if (startsWith(b, 'M', 'Z')) return "application/x-dosexec";   // executable — never allowed
        return null;
    }
    private boolean startsWith(byte[] b, char... sig) {
        if (b.length < sig.length) return false;
        for (int i = 0; i < sig.length; i++) if (b[i] != (byte) sig[i]) return false;
        return true;
    }
}

